// Draws each viz block from Box and Text, which every surface has; a graph
// or chart block is a picture where the surface has Image (the terminal),
// and elsewhere its dot source as code or its data as a table.

import type { ElementTable, RenderElement } from 'claude-code'

import { CELL_PX, NOTE, typesToDot } from './graph'
import type { Loaded, Rendered } from './graph'
import { nest, parseAt } from './parse'
import type {
  Chart,
  Compare,
  Graph,
  Node,
  Segment,
  Sequence,
  SequenceKind,
  Snippet,
  Status,
  Timeline,
  Trace,
  TraceKind,
  Tree,
  Types,
} from './parse'

type Els = Pick<ElementTable, 'Box' | 'Text' | 'Markdown' | 'Code'> & {
  Image?: ElementTable<'terminal'>['Image']
}

// What the render hook fetches for a block: a graph or chart's picture, a
// code block's lines; each pending, ready or failed.
export type Lookups = {
  picture: (block: Graph | Chart) => Rendered
  snippet: (block: Snippet) => Loaded
  note: (n: number, text: string, columns: number) => Rendered
}

const ACCENT = 'cyan'
const GOOD = 'green'

export const drawSegments = (els: Els, segments: Segment[], columns: number, lookups: Lookups): RenderElement => {
  const { Box } = els

  return (
    <Box flexDirection="column" gap={1}>
      {segments.map((s, i) => drawSegment(els, s, columns, lookups, `seg:${i}`))}
    </Box>
  )
}

const drawSegment = (els: Els, s: Segment, columns: number, lookups: Lookups, key: string): RenderElement => {
  const { Box, Text, Markdown } = els

  if (s.kind === 'markdown') return <Markdown key={key} text={s.text} />

  if (s.kind === 'pending') {
    return (
      <Text dimColor italic>
        ◌ drawing {s.hint}…
      </Text>
    )
  }

  if (s.kind === 'broken') {
    return (
      <Box flexDirection="column">
        <Markdown key={key} text={s.source} />
        <Text dimColor>viz: {s.reason}, shown as text</Text>
      </Box>
    )
  }

  // Inside the frame: two border columns and one of padding each side.
  const inner = Math.max(20, columns - 4)
  const body =
    s.viz.type === 'compare'
      ? drawCompare(els, s.viz, inner)
      : s.viz.type === 'timeline'
        ? drawTimeline(els, s.viz, inner)
        : s.viz.type === 'graph' || s.viz.type === 'chart'
          ? drawPicture(els, s.viz, inner, lookups.picture(s.viz))
          : s.viz.type === 'code'
            ? drawSnippet(els, s.viz, lookups.snippet(s.viz), inner, lookups.note)
            : s.viz.type === 'trace'
              ? drawTrace(els, s.viz, inner, lookups.snippet)
              : s.viz.type === 'sequence'
                ? drawSequence(els, s.viz, inner)
                : s.viz.type === 'types'
                  ? drawTypes(els, s.viz, inner, lookups.picture)
                  : drawTree(els, s.viz)

  return (
    <Box key={key} flexDirection="column" borderStyle="round" borderColor="gray" paddingX={1}>
      {s.viz.title !== undefined && (
        <Box marginBottom={1}>
          <Text bold color={ACCENT}>
            {s.viz.title}
          </Text>
        </Box>
      )}
      {body}
    </Box>
  )
}

// compare: options as columns, criteria as rows, the best cell of each row
// and the picked option marked; stacked cards when the columns would be too
// narrow to read.
const drawCompare = (els: Els, c: Compare, width: number): RenderElement => {
  const { Box, Text } = els
  const labelWidth = Math.min(22, Math.max(...c.criteria.map(r => r.name.length)) + 2)
  const optionWidth = Math.floor((width - labelWidth) / c.options.length)
  const isPick = (i: number) => c.pick === i

  const verdict = c.pick !== undefined && c.options[c.pick] !== undefined && (
    <Box marginTop={1}>
      <Text>
        <Text bold color={GOOD}>
          → {c.options[c.pick]}
        </Text>
        {c.why !== undefined && <Text>  {c.why}</Text>}
      </Text>
    </Box>
  )

  if (optionWidth < 14) {
    return (
      <Box flexDirection="column" gap={1}>
        {c.options.map((option, i) => (
          <Box flexDirection="column">
            <Text bold color={isPick(i) ? GOOD : undefined}>
              {isPick(i) ? '✓ ' : '  '}
              {option}
            </Text>
            {c.criteria.map(row => (
              <Text>
                <Text dimColor>  {row.name}: </Text>
                <Text color={row.best === i ? GOOD : undefined} bold={row.best === i}>
                  {row.values[i]}
                </Text>
              </Text>
            ))}
          </Box>
        ))}
        {verdict}
      </Box>
    )
  }

  return (
    <Box flexDirection="column">
      <Box flexDirection="row">
        <Box width={labelWidth}>
          <Text> </Text>
        </Box>
        {c.options.map((option, i) => (
          <Box width={optionWidth} paddingRight={1}>
            <Text bold color={isPick(i) ? GOOD : undefined}>
              {isPick(i) ? '✓ ' : ''}
              {option}
            </Text>
          </Box>
        ))}
      </Box>
      <Text dimColor>{'─'.repeat(Math.max(1, labelWidth + optionWidth * c.options.length - 1))}</Text>
      {c.criteria.map(row => (
        <Box flexDirection="row">
          <Box width={labelWidth}>
            <Text dimColor>
              {row.name}
            </Text>
          </Box>
          {row.values.map((value, i) => (
            <Box width={optionWidth} paddingRight={1}>
              <Text color={row.best === i ? GOOD : undefined} bold={row.best === i}>
                {row.best === i ? '▲ ' : ''}
                {value}
              </Text>
            </Box>
          ))}
        </Box>
      ))}
      {verdict}
    </Box>
  )
}

const GLYPH: Record<Status, { mark: string; color: string; strip: string }> = {
  done: { mark: '✔', color: GOOD, strip: '■' },
  active: { mark: '▶', color: ACCENT, strip: '■' },
  blocked: { mark: '✖', color: 'red', strip: '■' },
  todo: { mark: '○', color: 'gray', strip: '□' },
}

// timeline: a one-line progress strip, then the steps on a rail.
const drawTimeline = (els: Els, t: Timeline, width: number): RenderElement => {
  const { Box, Text } = els
  const done = t.steps.filter(s => s.status === 'done').length

  return (
    <Box flexDirection="column">
      <Box marginBottom={1}>
        <Text>
          {t.steps.map(s => (
            <Text color={GLYPH[s.status].color}>{GLYPH[s.status].strip} </Text>
          ))}
          <Text dimColor>
            {' '}
            {done}/{t.steps.length} done
          </Text>
        </Text>
      </Box>
      {t.steps.map((s, i) => {
        const g = GLYPH[s.status]
        const isLast = i === t.steps.length - 1

        return (
          <Box flexDirection="row">
            <Box flexDirection="column" width={2}>
              <Text color={g.color} bold>
                {g.mark}
              </Text>
              {!isLast && <Text dimColor>│</Text>}
            </Box>
            <Box flexDirection="column" width={Math.max(10, width - 2)}>
              <Text
                bold={s.status === 'active'}
                dimColor={s.status === 'todo'}
                color={s.status === 'blocked' ? 'red' : undefined}
              >
                {s.label}
              </Text>
              {s.detail !== undefined && <Text dimColor>{s.detail}</Text>}
            </Box>
          </Box>
        )
      })}
    </Box>
  )
}

const CHANGE = {
  add: { mark: '+', color: GOOD },
  edit: { mark: '~', color: 'yellow' },
  del: { mark: '-', color: 'red' },
} as const

// tree: flat paths drawn as a directory tree with change marks and notes.
const drawTree = (els: Els, t: Tree): RenderElement => {
  const { Box, Text } = els
  const count = (change: keyof typeof CHANGE) => t.items.filter(i => i.change === change).length
  const lines: RenderElement[] = []

  const walk = (nodes: Node[], prefix: string) => {
    nodes.forEach((node, i) => {
      const isLast = i === nodes.length - 1
      const isDir = node.children.length > 0
      const change = node.change !== undefined ? CHANGE[node.change] : undefined

      lines.push(
        <Text>
          <Text dimColor>
            {prefix}
            {isLast ? '└─ ' : '├─ '}
          </Text>
          {change !== undefined && (
            <Text color={change.color} bold>
              {change.mark}{' '}
            </Text>
          )}
          <Text
            bold={isDir}
            color={isDir ? 'blue' : change?.color}
            strikethrough={node.change === 'del'}
          >
            {node.name}
            {isDir ? '/' : ''}
          </Text>
          {node.note !== undefined && <Text dimColor>  {node.note}</Text>}
        </Text>,
      )
      walk(node.children, prefix + (isLast ? '   ' : '│  '))
    })
  }
  walk(nest(t.items), '')

  const tally = (['add', 'edit', 'del'] as const)
    .filter(c => count(c) > 0)
    .map(c => (
      <Text color={CHANGE[c].color}>
        {CHANGE[c].mark}
        {count(c)}{' '}
      </Text>
    ))

  return (
    <Box flexDirection="column">
      {lines}
      {tally.length > 0 && (
        <Box marginTop={1}>
          <Text>{tally}</Text>
        </Box>
      )}
    </Box>
  )
}

// A terminal cell is about half as wide as it is tall; at 144 dpi a cell
// spans about 14 pixels of the picture.
const CELL_ASPECT = 0.5
const PIXELS_PER_COLUMN = 14
const MAX_ROWS = 60
// Below this share of its natural size, a picture says how to see it whole.
const SHRUNK = 0.7

// graph and chart: the rendered picture, sized to its own aspect within the
// room; where there is no picture, what the block holds as text.
const drawPicture = (
  els: Els,
  block: Graph | Chart,
  width: number,
  rendered: Rendered,
  fallback?: RenderElement,
): RenderElement => {
  const { Box, Text, Code, Image } = els
  const noun = block.type === 'graph' ? 'diagram' : 'chart'

  if (rendered.kind === 'pending') {
    return (
      <Text dimColor italic>
        ◌ rendering {noun}…
      </Text>
    )
  }

  if (rendered.kind === 'failed' || Image === undefined) {
    return (
      <Box flexDirection="column">
        {fallback ?? (block.type === 'graph' ? <Code source={block.dot} language="dot" /> : drawChartData(els, block))}
        {rendered.kind === 'failed' && (
          <Text dimColor>
            {block.type}: {rendered.reason}
          </Text>
        )}
      </Box>
    )
  }

  const ratio = rendered.height / rendered.width
  const natural = Math.ceil(rendered.width / PIXELS_PER_COLUMN)
  let columns = Math.max(10, Math.min(width, natural))
  let rows = Math.max(1, Math.round(columns * ratio * CELL_ASPECT))
  if (rows > MAX_ROWS) {
    rows = MAX_ROWS
    columns = Math.max(10, Math.round(rows / ratio / CELL_ASPECT))
  }

  return (
    <Box flexDirection="column">
      <Image
        source={{ png: rendered.png }}
        columns={columns}
        rows={rows}
        alt={`[${noun}${block.title !== undefined ? `: ${block.title}` : ''}: this terminal shows no images]`}
      />
      {rendered.warning !== undefined && (
        <Text dimColor>
          {block.type}: {rendered.warning}
        </Text>
      )}
      {columns / natural < SHRUNK && (
        <Text dimColor>
          shrunk to {Math.round((columns / natural) * 100)}% · /viz-open to zoom
        </Text>
      )}
    </Box>
  )
}

const TABLE_COLUMNS = 5
const TABLE_ROWS = 10
const CELL_WIDTH = 16

// A chart without its picture: the first rows of its inline data.
const drawChartData = (els: Els, chart: Chart): RenderElement => {
  const { Box, Text } = els
  const data = chart.spec.data
  const values =
    typeof data === 'object' && data !== null && 'values' in data && Array.isArray(data.values)
      ? data.values.filter((row): row is Record<string, unknown> => typeof row === 'object' && row !== null)
      : []

  if (values.length === 0) return <Text dimColor>chart: no picture on this surface, and no inline rows to list</Text>

  const fields = Object.keys(values[0] ?? {}).slice(0, TABLE_COLUMNS)
  const cell = (value: unknown) => String(value ?? '').slice(0, CELL_WIDTH - 1)

  return (
    <Box flexDirection="column">
      <Box flexDirection="row">
        {fields.map(field => (
          <Box width={CELL_WIDTH}>
            <Text bold>{cell(field)}</Text>
          </Box>
        ))}
      </Box>
      {values.slice(0, TABLE_ROWS).map(row => (
        <Box flexDirection="row">
          {fields.map(field => (
            <Box width={CELL_WIDTH}>
              <Text>{cell(row[field])}</Text>
            </Box>
          ))}
        </Box>
      ))}
      {values.length > TABLE_ROWS && <Text dimColor>… {values.length - TABLE_ROWS} more rows</Text>}
    </Box>
  )
}

// ① to ⑳, then (21) and on.
const mark = (n: number): string => (n >= 1 && n <= 20 ? String.fromCodePoint(0x245f + n) : `(${n})`)

// A note's indent under the code; where a text note's marker ends and its
// text begins ("  ↳ ① ").
const NOTE_LEFT = 2
const NOTE_INDENT = 6
const NOTE_TINT = '#2a2418'

// code: the lines with the engine's highlighter, cut after each line a note
// points at so the note sits right under it; numbering runs on across cuts.
// A note is prose in a reading font where the terminal shows pictures, and
// tinted italic text elsewhere (and until its picture is ready).
const drawSnippet = (
  els: Els,
  s: Snippet,
  loaded: Loaded,
  width: number,
  noteLookup: Lookups['note'],
): RenderElement => {
  const { Box, Text, Code, Image } = els
  const imageColumns = Math.max(20, width - NOTE_LEFT)
  const textColumns = Math.max(20, width - NOTE_INDENT)

  const drawNote = (n: number, text: string): RenderElement => {
    const rendered = Image !== undefined ? noteLookup(n, text, imageColumns) : undefined

    // The picture carries its own numbered badge.
    if (Image !== undefined && rendered?.kind === 'ready') {
      return (
        <Box paddingLeft={NOTE_LEFT}>
          <Image
            source={{ png: rendered.png }}
            columns={imageColumns}
            rows={rendered.height / CELL_PX.height}
            alt={`${n}. ${text}`}
          />
        </Box>
      )
    }

    return (
      <Box flexDirection="row">
        <Box width={NOTE_INDENT}>
          <Text color={NOTE.color} bold>
            {'  '}↳ {mark(n)}
          </Text>
        </Box>
        <Box width={textColumns} backgroundColor={NOTE_TINT} paddingX={1}>
          <Text italic color={NOTE.color}>
            {text}
          </Text>
        </Box>
      </Box>
    )
  }
  const where =
    s.path !== undefined ? `${s.path}:${s.start ?? 1}${s.end !== undefined ? `–${s.end}` : ''}` : undefined

  const header = where !== undefined && (
    <Text dimColor>
      {where}
      {s.source === undefined ? '  (read from disk)' : ''}
    </Text>
  )

  if (loaded.kind === 'pending') {
    return (
      <Box flexDirection="column">
        {header}
        <Text dimColor italic>
          ◌ reading {s.path}…
        </Text>
      </Box>
    )
  }

  if (loaded.kind === 'failed') {
    return (
      <Box flexDirection="column">
        {header}
        <Text color="red">code: {loaded.reason}</Text>
      </Box>
    )
  }

  const lines = loaded.text.split('\n')
  const first = loaded.start
  const last = first + lines.length - 1
  const notes = (s.notes ?? []).map((note, i) => ({ ...note, n: i + 1 })).sort((a, b) => a.line - b.line)
  const shown = notes.filter(note => note.line >= first && note.line <= last)
  const outside = notes.filter(note => note.line < first || note.line > last)

  const parts: RenderElement[] = []
  let at = first
  const code = (from: number, to: number) => (
    <Code
      source={lines.slice(from - first, to - first + 1).join('\n')}
      startLine={from}
      language={s.language}
      path={s.path}
    />
  )

  for (const line of [...new Set(shown.map(note => note.line))]) {
    if (line >= at) parts.push(code(at, line))
    at = Math.max(at, line + 1)
    for (const note of shown.filter(n => n.line === line)) parts.push(drawNote(note.n, note.text))
  }
  if (at <= last) parts.push(code(at, last))

  return (
    <Box flexDirection="column">
      {header}
      {parts}
      {loaded.isCut && <Text dimColor>… cut at {lines.length} lines</Text>}
      {outside.map(note => (
        <Text dimColor>
          {mark(note.n)} line {note.line} is outside the snippet: {note.text}
        </Text>
      ))}
    </Box>
  )
}

const STEP: Record<TraceKind, { mark: string; color: string; label?: string }> = {
  call: { mark: '●', color: ACCENT },
  async: { mark: '◌', color: ACCENT, label: 'async' },
  effect: { mark: '◆', color: NOTE.color, label: 'effect' },
  return: { mark: '↩', color: 'gray' },
}

// Below this many columns a step's place goes under its text, not beside it.
const TRACE_SIDE_BY_SIDE = 72

const STEP_KEY: Record<TraceKind, string> = {
  call: 'call',
  async: 'runs later',
  effect: 'side effect',
  return: 'returns',
}

// The folder every path shares, as whole segments ("" when none).
const sharedFolder = (paths: string[]): string => {
  const split = paths.map(path => path.split('/').slice(0, -1))
  const first = split[0] ?? []
  let n = 0
  while (n < first.length && split.every(parts => parts[n] === first[n])) n += 1
  return first.slice(0, n).join('/')
}

// Lines with their shared leading whitespace taken off.
const dedent = (text: string): string => {
  const lines = text.split('\n')
  const indents = lines.filter(line => line.trim() !== '').map(line => /^[ \t]*/.exec(line)?.[0].length ?? 0)
  const cut = indents.length > 0 ? Math.min(...indents) : 0
  return lines.map(line => line.slice(cut)).join('\n')
}

// The call-tree guides before each step, as `tree` draws them: for each
// level above the step a bar where that level goes on below, then the
// step's own branch. A phase starts a fresh tree.
const treeGuides = (depths: number[], phaseStarts: boolean[]): { branch: string; under: string }[] => {
  const goesOn = (i: number, depth: number): boolean => {
    for (let j = i + 1; j < depths.length; j += 1) {
      if (phaseStarts[j]) return false
      const d = depths[j] ?? 0
      if (d < depth) return false
      if (d === depth) return true
    }
    return false
  }
  const ancestor = (i: number, depth: number): number => {
    for (let j = i - 1; j >= 0; j -= 1) {
      if ((depths[j] ?? 0) === depth) return j
      if (phaseStarts[j]) break
    }
    return -1
  }

  return depths.map((depth, i) => {
    let lead = ''
    for (let level = 1; level < depth; level += 1) {
      const a = ancestor(i, level)
      lead += a >= 0 && goesOn(a, level) ? '│  ' : '   '
    }
    if (depth === 0) return { branch: '', under: '' }
    const more = goesOn(i, depth)
    return { branch: lead + (more ? '├─ ' : '└─ '), under: lead + (more ? '│  ' : '   ') }
  })
}

// trace: one line per step: its number, call-tree guides, its kind, what
// happens, and where: the function, then the place (the folder all steps
// share said once, above). A phase
// heading marks a new stretch of time; a step's own lines from disk sit
// under it, dedented, behind a thin bar; a key names the marks in use.
const drawTrace = (els: Els, t: Trace, width: number, snippet: Lookups['snippet']): RenderElement => {
  const { Box, Text, Code } = els
  const places = t.steps.map(step => parseAt(step.at))
  const folder = sharedFolder(places.flatMap(place => (place !== undefined ? [place.path] : [])))
  const short = (path: string) => (folder !== '' ? path.slice(folder.length + 1) : path)
  const isSideBySide = width >= TRACE_SIDE_BY_SIDE
  const numberWidth = String(t.steps.length).length + 1
  const depths = t.steps.map(step => Math.min(step.depth ?? 0, 6))
  const guides = treeGuides(
    depths,
    t.steps.map((step, i) => i > 0 && step.phase !== undefined),
  )
  const kindsUsed = (['async', 'effect', 'return'] as const).filter(kind => t.steps.some(step => step.kind === kind))

  return (
    <Box flexDirection="column">
      {(folder !== '' || kindsUsed.length > 0) && (
        <Box marginBottom={1} flexDirection="row" justifyContent="space-between">
          <Text dimColor>{folder !== '' ? `in ${folder}/` : ''}</Text>
          {kindsUsed.length > 0 && (
            <Text>
              {kindsUsed.map(kind => (
                <Text>
                  <Text color={STEP[kind].color}>{STEP[kind].mark}</Text>
                  <Text dimColor> {STEP_KEY[kind]}  </Text>
                </Text>
              ))}
            </Text>
          )}
        </Box>
      )}
      {t.steps.map((step, i) => {
        const kind = STEP[step.kind ?? 'call']
        const place = places[i]
        const guide = guides[i] ?? { branch: '', under: '' }
        const where = place !== undefined ? `${short(place.path)}:${place.line}` : step.at
        const placeText = (
          <Text>
            {step.fn !== undefined && <Text color={ACCENT}>{step.fn}</Text>}
            <Text dimColor>
              {step.fn !== undefined ? ' · ' : ''}
              {where}
            </Text>
          </Text>
        )
        const shown =
          place !== undefined && (step.show ?? 0) > 0
            ? snippet({ type: 'code', path: place.path, start: place.line, end: place.line + (step.show ?? 1) - 1 })
            : undefined

        return (
          <Box flexDirection="column">
            {step.phase !== undefined && (
              <Box marginTop={i > 0 ? 1 : 0}>
                <Text color={ACCENT}>── {step.phase} ──</Text>
              </Box>
            )}
            <Box flexDirection="row">
              <Box width={numberWidth} flexShrink={0}>
                <Text dimColor>{i + 1}</Text>
              </Box>
              <Box flexShrink={0}>
                <Text dimColor>{guide.branch}</Text>
              </Box>
              <Box width={2} flexShrink={0}>
                <Text color={kind.color} bold>
                  {kind.mark}
                </Text>
              </Box>
              <Box flexDirection="column" flexGrow={1} flexShrink={1}>
                <Text bold={step.kind === 'effect'} color={step.kind === 'effect' ? NOTE.color : undefined}>
                  {step.what}
                </Text>
                {!isSideBySide && placeText}
              </Box>
              {isSideBySide && (
                <Box flexShrink={0} marginLeft={2}>
                  {placeText}
                </Box>
              )}
            </Box>
            {shown !== undefined && (
              <Box flexDirection="row">
                <Box width={numberWidth} flexShrink={0} />
                <Text dimColor>{guide.under}  ▏</Text>
                {shown.kind === 'ready' ? (
                  <Code source={dedent(shown.text)} path={place?.path} wrap="truncate-end" />
                ) : shown.kind === 'failed' ? (
                  <Text dimColor>
                    couldn't read {place !== undefined ? short(place.path) : step.at}: {shown.reason.replace(/^.*failed: /, '')}
                  </Text>
                ) : (
                  <Text dimColor italic>
                    reading…
                  </Text>
                )}
              </Box>
            )}
          </Box>
        )
      })}
    </Box>
  )
}

// types: shapes as tables, arrows from a field to what it refers to, laid
// out by Graphviz from the block (no dot written by the model); without a
// picture, the shapes and links as text.
const drawTypes = (els: Els, t: Types, width: number, picture: Lookups['picture']): RenderElement => {
  const { Box, Text } = els
  const graph: Graph = { type: 'graph', title: t.title, dot: typesToDot(t) }
  const asText = (
    <Box flexDirection="column">
      {t.shapes.map(shape => (
        <Text>
          <Text bold>{shape.name}</Text>
          {shape.kind !== undefined && <Text dimColor> {shape.kind}</Text>}
          <Text dimColor>: </Text>
          {shape.fields.map((field, i) => (
            <Text>
              {i > 0 ? ', ' : ''}
              {field.key !== undefined && <Text color={NOTE.color}>{field.key.toUpperCase()} </Text>}
              {field.name}
              {field.type !== undefined && <Text dimColor> {field.type}</Text>}
            </Text>
          ))}
        </Text>
      ))}
      {(t.links ?? []).map(link => (
        <Text dimColor>
          {link.from} → {link.to}
          {link.kind !== undefined && link.kind !== 'ref' ? ` (${link.kind})` : ''}
          {link.label !== undefined ? `: ${link.label}` : ''}
        </Text>
      ))}
    </Box>
  )

  return drawPicture(els, graph, width, picture(graph), asText)
}

type CellStyle = 'space' | 'life' | 'name' | 'label' | 'num' | SequenceKind
type Cell = { ch: string; style: CellStyle }

const ARROW: Record<SequenceKind, { line: string; right: string; left: string }> = {
  call: { line: '─', right: '▶', left: '◀' },
  reply: { line: '╌', right: '▶', left: '◀' },
  async: { line: '─', right: '▷', left: '◁' },
}

// Below this many columns between lifelines a sequence is listed instead.
const SEQUENCE_MIN_SPACING = 8
const SEQUENCE_MAX_SPACING = 32

// sequence: lifelines in columns, one numbered message per two rows (its
// text, then its arrow), drawn from text so it copies and fits any surface.
const drawSequence = (els: Els, s: Sequence, width: number): RenderElement => {
  const { Box, Text } = els
  const n = s.participants.length
  const longest = Math.max(...s.participants.map(p => p.length))
  const margin = Math.ceil(longest / 2)
  const spacing = Math.min(SEQUENCE_MAX_SPACING, Math.floor((width - 1 - 2 * margin) / (n - 1)))

  if (spacing < SEQUENCE_MIN_SPACING || longest > spacing + 2) {
    return (
      <Box flexDirection="column">
        {s.messages.map((m, i) => (
          <Text>
            <Text dimColor>{i + 1}. </Text>
            {m.from} <Text color={m.kind === 'async' ? NOTE.color : ACCENT}>{m.kind === 'reply' ? '⇠' : '→'}</Text> {m.to}
            <Text dimColor>: </Text>
            {m.text}
          </Text>
        ))}
      </Box>
    )
  }

  const centers = s.participants.map((_, i) => margin + i * spacing)
  const total = (centers[n - 1] ?? 0) + margin + 1
  const column = (name: string) => centers[s.participants.indexOf(name)] ?? 0

  const blank = (): Cell[] => {
    const row: Cell[] = Array.from({ length: total }, () => ({ ch: ' ', style: 'space' }))
    for (const c of centers) row[c] = { ch: '│', style: 'life' }
    return row
  }
  const put = (row: Cell[], at: number, text: string, style: CellStyle, max = total - at) => {
    const fitted = text.length > max ? `${text.slice(0, Math.max(0, max - 1))}…` : text
    ;[...fitted].forEach((ch, i) => {
      if (at + i >= 0 && at + i < total) row[at + i] = { ch, style }
    })
  }

  const header: Cell[] = Array.from({ length: total }, () => ({ ch: ' ', style: 'space' }))
  s.participants.forEach((name, i) => {
    const start = Math.min(Math.max(0, (centers[i] ?? 0) - Math.floor(name.length / 2)), total - name.length)
    put(header, start, name, 'name')
  })

  const rows: Cell[][] = [header, blank()]
  s.messages.forEach((m, i) => {
    const kind = m.kind ?? 'call'
    const from = column(m.from)
    const to = column(m.to)
    const number = `${i + 1}. `
    const label = blank()

    if (from === to) {
      put(label, from + 2, `↺ ${number}`, 'num')
      put(label, from + 4 + number.length, m.text, 'label')
      rows.push(label)
      return
    }

    const left = Math.min(from, to)
    const right = Math.max(from, to)
    const room = right - left - 3
    put(label, left + 2, number, 'num', room)
    put(label, left + 2 + number.length, m.text, 'label', Math.max(0, room - number.length))

    const arrow = blank()
    for (let x = left + 1; x < right; x += 1) arrow[x] = { ch: ARROW[kind].line, style: kind }
    if (from < to) arrow[right - 1] = { ch: ARROW[kind].right, style: kind }
    else arrow[left + 1] = { ch: ARROW[kind].left, style: kind }
    rows.push(label, arrow)
  })

  const color: Record<CellStyle, { color?: string; dimColor?: boolean; bold?: boolean }> = {
    space: {},
    life: { dimColor: true },
    name: { bold: true },
    label: {},
    num: { dimColor: true },
    call: { color: ACCENT },
    reply: { color: 'gray' },
    async: { color: NOTE.color },
  }

  // Each row as runs of one style, so a row is a handful of Texts.
  const draw = (row: Cell[]) => {
    const runs: { style: CellStyle; text: string }[] = []
    for (const cell of row) {
      const last = runs[runs.length - 1]
      if (last !== undefined && last.style === cell.style) last.text += cell.ch
      else runs.push({ style: cell.style, text: cell.ch })
    }
    return (
      <Text wrap="truncate-end">
        {runs.map(run => (
          <Text {...color[run.style]}>{run.text}</Text>
        ))}
      </Text>
    )
  }

  return <Box flexDirection="column">{rows.map(draw)}</Box>
}

files.hooks/graph.ts:
// What a graph or chart block's picture is while register.tsx renders it
// (Graphviz, or Vega-Lite through the mod's own vega-cli), and the pure
// pieces of that: where files go, what they are named, a chart's defaults,
// and how big the PNG is. (The engine follows `$` only into functions of the
// hooks module's own file, so the rendering lives there.)

export type Rendered =
  | { kind: 'pending' }
  | { kind: 'ready'; png: string; width: number; height: number; warning?: string }
  | { kind: 'failed'; reason: string }

export const RENDER_DIR = '/tmp/claude-viz-renders'

// The terminal's colors (Ghostty: black at 0.76 opacity, #c4c4c4 text).
// Pictures are transparent so the terminal's own background shows through.
export const THEME = {
  text: '#c4c4c4',
  muted: '#9e9e9e',
  grid: '#3a3a3a',
  frame: '#5a5a5a',
  font: 'Helvetica',
} as const

// Graphviz defaults for the theme; a graph's own attributes still win.
// `color` and `style` are what a cluster's frame takes: what lives inside
// what (package, file, function) is drawn as rounded grey frames.
export const DOT_THEME_ARGS = [
  '-Gbgcolor=transparent',
  `-Gcolor=${THEME.frame}`,
  '-Gstyle=rounded',
  `-Gfontcolor=${THEME.text}`,
  `-Gfontname=${THEME.font}`,
  `-Ncolor=${THEME.muted}`,
  `-Nfontcolor=${THEME.text}`,
  `-Nfontname=${THEME.font}`,
  `-Ecolor=${THEME.muted}`,
  `-Efontcolor=${THEME.text}`,
  `-Efontname=${THEME.font}`,
]

const objectOr = (value: unknown): Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value) ? (value as Record<string, unknown>) : {}

// Text sizes, about a third over Vega's defaults (10 for labels, 11 for
// axis titles, 13 for the chart title), so they read at terminal size.
const LABEL_SIZE = 13
const AXIS_TITLE_SIZE = 14
const TITLE_SIZE = 17

// Vega-Lite config for the theme: light text, grey axes and grid.
const CHART_THEME = {
  axis: {
    domainColor: THEME.muted,
    tickColor: THEME.muted,
    gridColor: THEME.grid,
    labelColor: THEME.text,
    titleColor: THEME.text,
    labelFontSize: LABEL_SIZE,
    titleFontSize: AXIS_TITLE_SIZE,
  },
  title: { color: THEME.text, subtitleColor: THEME.muted, fontSize: TITLE_SIZE, subtitleFontSize: LABEL_SIZE },
  legend: { labelColor: THEME.text, titleColor: THEME.text, labelFontSize: LABEL_SIZE, titleFontSize: LABEL_SIZE },
  header: { labelColor: THEME.text, titleColor: THEME.text, labelFontSize: LABEL_SIZE, titleFontSize: AXIS_TITLE_SIZE },
  text: { color: THEME.text, fontSize: LABEL_SIZE },
}

// A chart's spec as rendered: the theme, a transparent background, and a
// wide default view (Vega-Lite otherwise gives each bar a fixed step, tall
// and narrow on a terminal). The spec's own settings win over all of these.
export const chartSpec = (spec: Record<string, unknown>): Record<string, unknown> => {
  const config = objectOr(spec.config)

  return {
    ...spec,
    background: spec.background ?? 'transparent',
    padding: spec.padding ?? 12,
    config: {
      ...CHART_THEME,
      ...config,
      view: {
        stroke: THEME.grid,
        continuousWidth: 480,
        continuousHeight: 240,
        discreteWidth: 480,
        ...objectOr(config.view),
      },
    },
  }
}

// FNV-1a, enough to name a file by its source.
export const hash = (text: string): string => {
  let h = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 0x01000193)
  }
  return (h >>> 0).toString(16).padStart(8, '0')
}

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

// The first bytes of standard base64, decoded: enough for a PNG header.
const decodeHead = (base64: string, count: number): Uint8Array => {
  const out = new Uint8Array(count)
  let bits = 0
  let value = 0
  let at = 0
  for (const char of base64) {
    if (at === count) break
    const digit = ALPHABET.indexOf(char)
    if (digit < 0) break
    value = (value << 6) | digit
    bits += 6
    if (bits >= 8) {
      bits -= 8
      out[at++] = (value >> bits) & 0xff
    }
  }
  return out.subarray(0, at)
}

// A PNG's IHDR holds its width and height, big-endian, at bytes 16 and 20.
export const pngSize = (base64: string): { width: number; height: number } | undefined => {
  const head = decodeHead(base64, 24)
  const isPng = head.length === 24 && head[0] === 0x89 && head[1] === 0x50 && head[2] === 0x4e && head[3] === 0x47
  if (!isPng) return undefined

  const view = new DataView(head.buffer, head.byteOffset, head.byteLength)
  return { width: view.getUint32(16), height: view.getUint32(20) }
}

// A code block's lines while register.tsx reads them from disk.
export type Loaded =
  | { kind: 'pending' }
  | { kind: 'ready'; text: string; start: number; isCut: boolean }
  | { kind: 'failed'; reason: string }

// Lines `start` to `end` (1-based, inclusive) of a file's text, at most
// `max` of them; `end` absent, from `start` for `max` lines.
export const sliceLines = (text: string, start: number, end: number | undefined, max: number): Loaded => {
  const lines = text.split('\n')
  if (start > lines.length) return { kind: 'failed', reason: `the file has ${lines.length} lines, fewer than ${start}` }

  const wanted = Math.min(end ?? start + max - 1, lines.length)
  const last = Math.min(wanted, start + max - 1)

  return { kind: 'ready', text: lines.slice(start - 1, last).join('\n'), start, isCut: last < wanted }
}

// Code-block notes drawn as pictures: prose in the system's reading font, a
// size over the terminal's, so a note reads as commentary rather than code.
// The text goes to ImageMagick through a file, where it stays literal (no
// `@file` reads, no `%` escapes, as a command-line `caption:` argument has).
export const NOTE = {
  font: '/System/Library/Fonts/SFNS.ttf',
  color: '#e5c07b',
  points: 32,
  interline: 6,
  // The numbered badge before the text: its square, the slot it is
  // centred in, and its digit.
  badge: 40,
  badgeSlot: 56,
  badgeText: '#1c1c1c',
  badgePoints: 26,
  // One line of text at `points`, measured: the badge lines up with it.
  lineHeight: 45,
} as const

// A terminal cell in picture pixels, as the 144 dpi pictures are drawn: a
// note is rendered at its columns' width and padded to whole rows, so the
// Image box holds it unstretched.
export const CELL_PX = { width: 14, height: 28 } as const

// Text for a Graphviz HTML-like label: its markup characters escaped.
const html = (text: string): string =>
  text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

type TypesInput = {
  shapes: { name: string; kind?: string; fields: { name: string; type?: string; key?: 'pk' | 'fk' }[]; note?: string }[]
  links?: { from: string; to: string; kind?: 'ref' | 'many-to-one' | 'one-to-one' | 'many-to-many'; label?: string }[]
}

// The ends of each link kind, read from the `from` side: a plain arrow for
// "refers to"; crow's foot for many and a bar for one, for tables.
const LINK_ENDS = {
  ref: 'arrowhead=normal',
  'many-to-one': 'dir=both, arrowtail=crow, arrowhead=tee',
  'one-to-one': 'dir=both, arrowtail=tee, arrowhead=tee',
  'many-to-many': 'dir=both, arrowtail=crow, arrowhead=crow',
} as const

// A types block as Graphviz source: each shape a table (its name and kind,
// then a row per field with its key and type), each link an arrow from a
// field row to a shape or field. Nodes and ports get generated ids, so no
// name reaches the source outside an escaped label.
export const typesToDot = (types: TypesInput): string => {
  const ids = new Map<string, string>()
  const nodes = types.shapes.map((shape, n) => {
    ids.set(shape.name, `s${n}`)
    const rows = shape.fields.map((field, f) => {
      ids.set(`${shape.name}.${field.name}`, `s${n}:f${f}`)
      const key = field.key !== undefined ? `<font color="${NOTE.color}">${field.key.toUpperCase()}</font>  ` : ''
      const type = field.type !== undefined ? `  <font color="${THEME.muted}">${html(field.type)}</font>` : ''
      return `<tr><td port="f${f}" align="left">${key}${html(field.name)}${type}</td></tr>`
    })
    const kind = shape.kind !== undefined ? `  <font color="${THEME.muted}">${html(shape.kind)}</font>` : ''
    const note =
      shape.note !== undefined
        ? `<tr><td align="left"><i><font color="${THEME.muted}">${html(shape.note)}</font></i></td></tr>`
        : ''
    return (
      `s${n} [label=<<table border="0" cellborder="1" cellspacing="0" cellpadding="6" color="${THEME.muted}">` +
      `<tr><td bgcolor="#2b2b2b" align="left"><b>${html(shape.name)}</b>${kind}</td></tr>${rows.join('')}${note}</table>>];`
    )
  })
  const edges = (types.links ?? []).flatMap(link => {
    const from = ids.get(link.from)
    const to = ids.get(link.to)
    if (from === undefined || to === undefined) return []
    const label = link.label !== undefined ? `, label=<${html(link.label)}>` : ''
    return [`${from} -> ${to} [${LINK_ENDS[link.kind ?? 'ref']}${label}];`]
  })

  // Left to right reads best in place, though a wide one is shrunk to fit;
  // /viz-open shows it full size.
  return `digraph { rankdir=LR; node [shape=plain]; ${nodes.join(' ')} ${edges.join(' ')} }`
}

files.hooks/hold.ts:
// Holds a streaming reply back from the moment a ```viz fence opens in a
// text block until that block ends, so the person never watches raw JSON
// stream in; the block then arrives whole and the render hook draws it.
// `onHold` hears the held block's type, or undefined once nothing is held.
//
// Nothing is rewritten: every chunk leaves in the order it came, engine
// chunks (a block's start and end) included, only later. A block ends when
// a chunk of another block, or the stop, arrives; the stream's end flushes.

import type { TurnStepChunk } from 'claude-code'

export async function* holdViz(
  stream: AsyncIterable<TurnStepChunk>,
  onHold: (type: string | undefined) => void,
): AsyncGenerator<TurnStepChunk, void> {
  let held: TurnStepChunk[] = []
  let holding: number | undefined
  let block: number | undefined
  let text = ''
  let hint: string | undefined

  const say = (next: string | undefined) => {
    if (next !== hint) onHold((hint = next))
  }

  try {
    for await (const chunk of stream) {
      const index = 'index' in chunk ? chunk.index : undefined
      const endsHeld = holding !== undefined && (chunk.kind === 'stop' || (index !== undefined && index !== holding))

      if (endsHeld) {
        yield* held
        held = []
        holding = undefined
        say(undefined)
      }

      if (chunk.kind === 'text') {
        if (chunk.index !== block) {
          block = chunk.index
          text = ''
        }
        text += chunk.text
        if (holding === undefined && text.includes('```viz')) holding = chunk.index
      }

      if (holding === undefined) {
        yield chunk
        continue
      }

      held.push(chunk)
      const type = /"type"\s*:\s*"(\w+)"/.exec(text.slice(text.lastIndexOf('```viz')))?.[1]
      say(type ?? 'visual')
    }

    yield* held
  } finally {
    say(undefined)
  }
}

files.hooks/parse.ts:
// Splits an assistant text block into markdown and ```viz segments, and
// checks each viz block's JSON against the vocabulary the prompt teaches.

export type Status = 'done' | 'active' | 'todo' | 'blocked'
export type Change = 'add' | 'edit' | 'del'

export type Compare = {
  type: 'compare'
  title?: string
  options: string[]
  criteria: { name: string; values: string[]; best?: number }[]
  pick?: number
  why?: string
}

export type Timeline = {
  type: 'timeline'
  title?: string
  steps: { label: string; detail?: string; status: Status }[]
}

export type Tree = {
  type: 'tree'
  title?: string
  items: { path: string; note?: string; change?: Change }[]
}

// graph: Graphviz source, laid out and drawn by the host's `dot`.
export type Graph = {
  type: 'graph'
  title?: string
  dot: string
}

// chart: a Vega-Lite spec with its data inline, drawn by vl2svg.
export type Chart = {
  type: 'chart'
  title?: string
  spec: Record<string, unknown>
}

// code: a snippet with numbered callouts pinned to its lines. Given `path`
// and `start` (and `end`), the lines are read from disk, so what shows is
// the file itself; `source` is for code that is in no file.
export type Snippet = {
  type: 'code'
  title?: string
  path?: string
  start?: number
  end?: number
  source?: string
  language?: string
  notes?: { line: number; text: string }[]
}

// trace: an execution path, step by step: where (`file:line`, and the
// function or class it is in), what happens there, what kind of step it is, how deep in the calls, optionally a few of
// its lines read from disk, and a `phase` that starts a new stretch of time
// (a later callback, a second pass).
export type TraceKind = 'call' | 'async' | 'effect' | 'return'

export type Trace = {
  type: 'trace'
  title?: string
  steps: {
    at: string
    what: string
    fn?: string
    kind?: TraceKind
    depth?: number
    show?: number
    phase?: string
  }[]
}

// sequence: who calls whom, in order. A message's kind: a call (solid), a
// reply (dashed back), or async (fire and forget).
export type SequenceKind = 'call' | 'reply' | 'async'

export type Sequence = {
  type: 'sequence'
  title?: string
  participants: string[]
  messages: { from: string; to: string; text: string; kind?: SequenceKind }[]
}

// types: shapes (interfaces, types, classes, tables) with their fields, and
// links from a field to the shape or field it refers to. A link is a plain
// "refers to" arrow; the database kinds draw crow's feet for many.
export type LinkKind = 'ref' | 'many-to-one' | 'one-to-one' | 'many-to-many'

export type Types = {
  type: 'types'
  title?: string
  shapes: { name: string; kind?: string; fields: { name: string; type?: string; key?: 'pk' | 'fk' }[]; note?: string }[]
  links?: { from: string; to: string; kind?: LinkKind; label?: string }[]
}

export type Viz = Compare | Timeline | Tree | Graph | Chart | Snippet | Trace | Sequence | Types

// `path:line` as a trace step names its place; undefined when it does not.
export const parseAt = (at: string): { path: string; line: number } | undefined => {
  const match = /^(.+):(\d+)$/.exec(at.trim())
  const line = Number(match?.[2])
  return match?.[1] !== undefined && line >= 1 ? { path: match[1], line } : undefined
}

// The most lines one trace step may show.
export const TRACE_MAX_SHOW = 8

// The most lines a code block shows, read from disk or given inline.
export const SNIPPET_MAX_LINES = 80

export type Segment =
  | { kind: 'markdown'; text: string }
  | { kind: 'viz'; viz: Viz }
  | { kind: 'pending'; hint: string }
  | { kind: 'broken'; source: string; reason: string }

const FENCE = /```viz[^\S\n]*\n([\s\S]*?)\n?```/g
const OPEN_FENCE = /```viz[^\S\n]*(\n[\s\S]*)?$/

export const hasViz = (text: string): boolean => text.includes('```viz')

export const segment = (text: string): Segment[] => {
  const out: Segment[] = []
  let at = 0

  for (const match of text.matchAll(FENCE)) {
    pushMarkdown(out, text.slice(at, match.index))
    out.push(toSegment(match[1] ?? '', match[0]))
    at = match.index + match[0].length
  }

  const rest = text.slice(at)
  const open = OPEN_FENCE.exec(rest)

  if (open) {
    // An unclosed fence: the reply is still streaming in.
    pushMarkdown(out, rest.slice(0, open.index))
    const type = /"type"\s*:\s*"(\w+)"/.exec(open[1] ?? '')?.[1]
    out.push({ kind: 'pending', hint: type ?? 'visual' })
  } else {
    pushMarkdown(out, rest)
  }

  return out
}

const pushMarkdown = (out: Segment[], text: string) => {
  if (text.trim() !== '') out.push({ kind: 'markdown', text: text.trim() })
}

const toSegment = (body: string, source: string): Segment => {
  let data: unknown

  try {
    data = JSON.parse(body)
  } catch (error) {
    return { kind: 'broken', source, reason: 'not valid JSON' }
  }

  const reason = check(data)

  return reason === undefined
    ? { kind: 'viz', viz: data as Viz }
    : { kind: 'broken', source, reason }
}

const isObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v)

const isStrings = (v: unknown): v is string[] =>
  Array.isArray(v) && v.every(s => typeof s === 'string')

// Whether `key` appears anywhere in a JSON value, however deep.
const hasKey = (value: unknown, key: string): boolean => {
  if (Array.isArray(value)) return value.some(item => hasKey(item, key))
  if (!isObject(value)) return false
  return Object.entries(value).some(([k, v]) => k === key || hasKey(v, key))
}

const STATUSES: readonly string[] = ['done', 'active', 'todo', 'blocked']
const CHANGES: readonly string[] = ['add', 'edit', 'del']

// Returns why `data` is not a viz block, or undefined when it is one.
export const check = (data: unknown): string | undefined => {
  if (!isObject(data)) return 'not an object'

  if (data.type === 'compare') {
    if (!isStrings(data.options) || data.options.length < 2) return 'compare needs 2+ options'
    const width = data.options.length
    if (!Array.isArray(data.criteria) || data.criteria.length === 0) return 'compare needs criteria'
    const isCriterion = (c: unknown) =>
      isObject(c) && typeof c.name === 'string' && isStrings(c.values) && c.values.length === width
    if (!data.criteria.every(isCriterion)) return `each criterion needs a name and ${width} values`
    return undefined
  }

  if (data.type === 'timeline') {
    const isStep = (s: unknown) =>
      isObject(s) && typeof s.label === 'string' && STATUSES.includes(String(s.status))
    if (!Array.isArray(data.steps) || !data.steps.every(isStep)) return 'each step needs a label and a status'
    return undefined
  }

  if (data.type === 'tree') {
    const isItem = (i: unknown) =>
      isObject(i) && typeof i.path === 'string' && (i.change === undefined || CHANGES.includes(String(i.change)))
    if (!Array.isArray(data.items) || !data.items.every(isItem)) return 'each item needs a path'
    return undefined
  }

  if (data.type === 'graph') {
    if (typeof data.dot !== 'string' || !/^\s*(strict\s+)?(di)?graph\b/.test(data.dot)) return 'graph needs "dot": a digraph { ... } or graph { ... }'
    return undefined
  }

  if (data.type === 'chart') {
    if (!isObject(data.spec)) return 'chart needs "spec": a Vega-Lite object'
    const views = ['mark', 'layer', 'concat', 'hconcat', 'vconcat', 'facet', 'repeat']
    if (!views.some(view => view in (data.spec as object))) return 'chart spec needs a mark (or layer, concat, facet, repeat)'
    // The renderer must not fetch anything: data rides in the spec.
    if (hasKey(data.spec, 'url')) return 'chart data must be inline ("data": {"values": [...]}), not a url'
    return undefined
  }

  if (data.type === 'code') {
    const isLine = (n: unknown): n is number => typeof n === 'number' && Number.isInteger(n) && n >= 1
    const hasSource = typeof data.source === 'string'
    const hasFile = typeof data.path === 'string' && isLine(data.start)
    if (!hasSource && !hasFile) return 'code needs "path" and "start" (lines read from the file), or "source"'
    if (data.end !== undefined && !(isLine(data.end) && isLine(data.start) && data.end >= data.start)) {
      return 'code "end" must be a line number at or after "start"'
    }
    if (hasFile && isLine(data.end) && data.end - (data.start as number) + 1 > SNIPPET_MAX_LINES) {
      return `code shows at most ${SNIPPET_MAX_LINES} lines`
    }
    const isNote = (n: unknown) => isObject(n) && isLine(n.line) && typeof n.text === 'string'
    if (data.notes !== undefined && !(Array.isArray(data.notes) && data.notes.every(isNote))) {
      return 'each code note needs a "line" number and a "text"'
    }
    return undefined
  }

  if (data.type === 'trace') {
    const kinds: readonly unknown[] = ['call', 'async', 'effect', 'return']
    const isStep = (step: unknown) =>
      isObject(step) &&
      typeof step.at === 'string' &&
      parseAt(step.at) !== undefined &&
      typeof step.what === 'string' &&
      (step.kind === undefined || kinds.includes(step.kind)) &&
      (step.depth === undefined || (Number.isInteger(step.depth) && (step.depth as number) >= 0)) &&
      (step.phase === undefined || typeof step.phase === 'string') &&
      (step.fn === undefined || typeof step.fn === 'string') &&
      (step.show === undefined ||
        (Number.isInteger(step.show) && (step.show as number) >= 0 && (step.show as number) <= TRACE_MAX_SHOW))
    if (!Array.isArray(data.steps) || data.steps.length === 0) return 'trace needs steps'
    if (!data.steps.every(isStep)) {
      return `each trace step needs "at" as path:line and "what"; kind is call, async, effect or return; show at most ${TRACE_MAX_SHOW}`
    }
    return undefined
  }

  if (data.type === 'sequence') {
    if (!isStrings(data.participants) || data.participants.length < 2) return 'sequence needs 2+ participants'
    const names: readonly unknown[] = data.participants
    const kinds: readonly unknown[] = ['call', 'reply', 'async']
    const isMessage = (m: unknown) =>
      isObject(m) &&
      names.includes(m.from) &&
      names.includes(m.to) &&
      typeof m.text === 'string' &&
      (m.kind === undefined || kinds.includes(m.kind))
    if (!Array.isArray(data.messages) || data.messages.length === 0) return 'sequence needs messages'
    if (!data.messages.every(isMessage)) return 'each message needs "from" and "to" among the participants, and "text"; kind is call, reply or async'
    return undefined
  }

  if (data.type === 'types') {
    const isField = (f: unknown) =>
      isObject(f) &&
      typeof f.name === 'string' &&
      (f.type === undefined || typeof f.type === 'string') &&
      (f.key === undefined || f.key === 'pk' || f.key === 'fk')
    const isShape = (sh: unknown) =>
      isObject(sh) &&
      typeof sh.name === 'string' &&
      (sh.kind === undefined || typeof sh.kind === 'string') &&
      Array.isArray(sh.fields) &&
      sh.fields.every(isField)
    if (!Array.isArray(data.shapes) || data.shapes.length === 0 || !data.shapes.every(isShape)) {
      return 'types needs shapes, each with a "name" and "fields" ({"name", "type"?})'
    }
    const names = new Set(
      (data.shapes as { name: string; fields: { name: string }[] }[]).flatMap(sh => [
        sh.name,
        ...sh.fields.map(f => `${sh.name}.${f.name}`),
      ]),
    )
    const kinds: readonly unknown[] = ['ref', 'many-to-one', 'one-to-one', 'many-to-many']
    const isLink = (l: unknown) =>
      isObject(l) && names.has(String(l.from)) && names.has(String(l.to)) && (l.kind === undefined || kinds.includes(l.kind))
    if (data.links !== undefined && !(Array.isArray(data.links) && data.links.every(isLink))) {
      return 'each link needs "from" and "to" naming a shape or Shape.field; kind is ref, many-to-one, one-to-one or many-to-many'
    }
    return undefined
  }

  return `unknown type ${JSON.stringify(data.type)}`
}

// A tree block's flat paths as nested nodes, directories first.
export type Node = { name: string; note?: string; change?: Change; children: Node[] }

export const nest = (items: Tree['items']): Node[] => {
  const root: Node = { name: '', children: [] }

  for (const item of items) {
    let at = root
    for (const part of item.path.split('/').filter(Boolean)) {
      let child = at.children.find(c => c.name === part)
      if (!child) {
        child = { name: part, children: [] }
        at.children.push(child)
      }
      at = child
    }
    at.note = item.note
    at.change = item.change
  }

  const sort = (nodes: Node[]): Node[] =>
    nodes
      .map(n => ({ ...n, children: sort(n.children) }))
      .sort((a, b) => Number(b.children.length > 0) - Number(a.children.length > 0))

  return sort(root.children)
}

